cd logs; python3 - <<'PY'
import re,datetime
conv=lambda s: datetime.datetime.strptime(s,'%d/%b/%Y:%H:%M:%S %z')
a=datetime.datetime.fromisoformat('2026-10-29T06:58:41.337+00:00')
xs=[]
for l in open('gateway.log'):
    if ' 502 ' in l:
        m=re.match(r'(\S+ \S+) "([^"]*)" 502 req=(\w+) upstream=(\w+)',l)
        t=conv(m.group(1))
        if t>=a: xs.append((t,m.groups()))
xs.sort()
for t,g in xs[:20]: print(t,g)
PY
